pub fn parse_n<I>(mut args: I) -> i32
where
    I: Iterator<Item = String>,
{
    let _program = args.next();
    args.next().map_or(10, |value| c_atoi(&value))
}

fn c_atoi(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && is_c_whitespace(bytes[index]) {
        index += 1;
    }

    let mut sign = 1i32;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i32;
    let mut saw_digit = false;

    while index < bytes.len() {
        let digit = match bytes[index] {
            b'0'..=b'9' => (bytes[index] - b'0') as i32,
            _ => break,
        };

        saw_digit = true;
        value = value.saturating_mul(10).saturating_add(digit);
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    value.saturating_mul(sign)
}

fn is_c_whitespace(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
}

#[cfg(test)]
mod tests {
    use super::parse_n;

    #[test]
    fn defaults_to_ten() {
        assert_eq!(parse_n(["prog".to_string()].into_iter()), 10);
    }

    #[test]
    fn matches_basic_atoi_cases() {
        assert_eq!(parse_n(["prog", "1x"].map(str::to_string).into_iter()), 1);
        assert_eq!(parse_n(["prog", "   1"].map(str::to_string).into_iter()), 1);
        assert_eq!(parse_n(["prog", "abc"].map(str::to_string).into_iter()), 0);
        assert_eq!(parse_n(["prog", "-1x"].map(str::to_string).into_iter()), -1);
    }
}

